jsLib:
var VEDA="https://ved.chyxcw.com/api/v3";
function vedToken(){
  var t="";
  try{t=String(source.get("vedTok")||"");}catch(e){}
  if(t&&t.length>50)return t;
  try{
    var dev="h5_"+String(java.randomUUID()).replace(/-/g,"");
    var opt=JSON.stringify({method:"POST",body:JSON.stringify({device_id:dev}),headers:{"Content-Type":"application/json","User-Agent":"Mozilla/5.0"},charset:"UTF-8"});
    var resp=String(java.ajax(VEDA+"/auth/guest,"+opt,15000));
    var j=JSON.parse(resp);
    if(j&&j.data&&j.data.access_token){
      try{source.put("vedTok",j.data.access_token);}catch(e){}
      var opt2=JSON.stringify({method:"POST",body:"{}",headers:{"Content-Type":"application/json","Authorization":"Bearer "+j.data.access_token},charset:"UTF-8"});
      try{java.ajax(VEDA+"/me/adult-confirmations,"+opt2,15000);}catch(e){}
      return j.data.access_token;
    }
  }catch(e){}
  return "";
}
function vedGet(path){
  try{
    var tok=vedToken();
    var h={"User-Agent":"Mozilla/5.0","Accept":"application/json","Referer":"https://shorttv.online/","Origin":"https://shorttv.online"};
    if(tok)h["Authorization"]="Bearer "+tok;
    var opt=JSON.stringify({method:"GET",headers:h,charset:"UTF-8"});
    var resp=String(java.ajax(VEDA+path+","+opt,15000));
    var j=JSON.parse(resp);
    return j&&j.data?j.data:null;
  }catch(e){return null;}
}
function vedUnlock(episodeId){
  try{
    var tok=vedToken();
    if(!tok)return false;
    var opt=JSON.stringify({method:"POST",body:"{}",headers:{"Content-Type":"application/json","Authorization":"Bearer "+tok,"Idempotency-Key":String(java.randomUUID())},charset:"UTF-8"});
    var resp=String(java.ajax(VEDA+"/me/commerce/episode-unlocks/"+episodeId+","+opt,15000));
    var j=JSON.parse(resp);
    return !!(j&&j.status===true);
  }catch(e){return false;}
}

ruleBookInfo.init:
@js:(function(){
  var m=String(baseUrl||'').match(/\/watch\/([^\/]+)/);
  var did=m?m[1]:'';
  var d=vedGet('/public/dramas/'+did);
  if(!d)return {};
  try{source.put('vedDetail',JSON.stringify(d));}catch(e){}
  var cats='';
  try{cats=(d.categories||[]).map(function(x){return x.title||x.name||x;}).join(',')||'';}catch(e){}
  return {name:d.title||'',coverUrl:d.cover_url||d.poster_url||'',intro:d.description||'',kind:cats};
})()

ruleToc.chapterList:
@js:(function(){
  var d={};try{d=JSON.parse(source.get('vedDetail')||'{}');}catch(e){}
  var eps=d.episodes||[];var did=d.id||'';
  var out=[];
  for(var i=0;i<eps.length;i++){var e=eps[i];
    var nm=e.title||('第'+(e.index||i+1)+'集');
    nm=String(nm).replace(/_第\d+集$/,'');
    out.push({name:nm,url:'https://shorttv.online/webpc/watch/'+did+'/'+(e.index||i+1),isPay:e.is_free?'':'1'});
  }
  return JSON.stringify(out);
})()

ruleContent.content:
@js:(function(){
  var m=String(baseUrl||'').match(/\/watch\/([^\/]+)\/(\d+)/);
  var did=m?m[1]:'';var idx=m?m[2]:'1';
  var d=vedGet('/me/dramas/'+did+'/episodes/'+idx+'/playback');
  if(d&&d.episode&&d.episode.playback_url)return d.episode.playback_url;
  if(d&&d.episode&&d.episode.locked){
    var eid=d.episode.id;
    var ok=false;
    if(eid){ok=vedUnlock(eid);}
    if(ok){
      var d2=vedGet('/me/dramas/'+did+'/episodes/'+idx+'/playback');
      if(d2&&d2.episode&&d2.episode.playback_url)return d2.episode.playback_url;
    }
    return '本集为付费内容。请登录账号并签到攒金币，金币足够时自动解锁播放。';
  }
  return '';
})()

loginUrl:
function readAcc(){
  try{java.upLoginData();}catch(e){}
  var u="",p="";
  try{var map=source.getLoginInfoMap();if(map){if(typeof map.get==="function"){u=String(map.get("账号")||"");p=String(map.get("密码")||"");}else{u=String(map["账号"]||"");p=String(map["密码"]||"");}}}catch(e){}
  return {u:u,p:p};
}
function doAuth(path){
  var r=readAcc();
  if(!r.u||!r.p){java.toast("请填写账号密码");return null;}
  try{
    var dev="h5_"+String(java.randomUUID()).replace(/-/g,"");
    var opt=JSON.stringify({method:"POST",body:JSON.stringify({device_id:dev,identifier:r.u,password:r.p,display_name:r.u}),headers:{"Content-Type":"application/json"},charset:"UTF-8"});
    var resp=String(java.ajax(VEDA+path+","+opt,15000));
    var j=JSON.parse(resp);
    if(j&&j.data&&j.data.access_token){try{source.put("vedTok",j.data.access_token);}catch(e){}}
    return j;
  }catch(e){java.toast("请求错误："+e);return null;}
}
function login(){
  var j=doAuth("/auth/login");
  if(!j)return;
  if(j.status===true){java.longToast("登录成功");}else{java.toast("登录失败："+(j.message||""));}
}
function reg(){
  var j=doAuth("/auth/register");
  if(!j)return;
  if(j.status===true){java.longToast("注册成功，已自动登录（注册送100CT）");}else{java.toast("注册失败："+(j.message||""));}
}
function checkin(){
  try{
    var tok=vedToken();
    var opt=JSON.stringify({method:"POST",body:"{}",headers:{"Content-Type":"application/json","Authorization":"Bearer "+tok,"Idempotency-Key":String(java.randomUUID())},charset:"UTF-8"});
    var resp=String(java.ajax(VEDA+"/me/tasks/checkin/claims,"+opt,15000));
    var j=JSON.parse(resp);
    if(j&&j.status===true){java.longToast("签到成功 +10金币");}else{java.toast("签到："+(j.message||"失败"));}
  }catch(e){java.toast("签到错误："+e);}
}
function help(){
  java.longToast("游客可看免费集；注册登录后每日签到攒金币，播放付费集自动用金币解锁。");
}
